package com.bank.statement.repository;

import com.bank.statement.model.Transaction;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.repository.*;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface TxnRepository extends JpaRepository<Transaction, Long> {

    // OFFSET pagination (Pageable → LIMIT/OFFSET) — slow for deep pages
    Page<Transaction> findByAccountId(String accountId, Pageable pageable);

    // KEYSET pagination — seek past the last seen id, constant time
    @Query("select t from Transaction t where t.accountId = :acct and t.id < :lastId " +
           "order by t.id desc")
    List<Transaction> keysetPage(@Param("acct") String acct,
                                 @Param("lastId") Long lastId, Pageable limit);
}
