package com.bank.statement.service;

import com.bank.statement.model.Transaction;
import com.bank.statement.repository.TxnRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Slf4j
@Service
@RequiredArgsConstructor
public class StatementService {
    private final TxnRepository repo;

    // OFFSET: fine for shallow pages, slow when pageNumber is large
    @Transactional(readOnly = true)
    public Page<Transaction> offsetPage(String acct, int pageNumber, int size) {
        Pageable p = PageRequest.of(pageNumber, size, Sort.by(Sort.Direction.DESC, "id"));
        Page<Transaction> result = repo.findByAccountId(acct, p);
        if (pageNumber > 1000)
            log.warning(() -> "Deep offset page " + pageNumber + " — expect slowdown");
        return result;
    }

    // KEYSET: pass the last id from the previous page; constant time
    @Transactional(readOnly = true)
    public List<Transaction> keysetPage(String acct, Long lastSeenId, int size) {
        Long anchor = lastSeenId == null ? Long.MAX_VALUE : lastSeenId;
        List<Transaction> page = repo.keysetPage(acct, anchor, PageRequest.of(0, size));
        log.info("Keyset page of {} after id {}", page.size(), lastSeenId);
        return page;  // client uses last element's id as next anchor
    }
}
